const sets={"interface-mobile": {"before": ["data:image/jpeg;base64,"], "after": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "note": "修改前为历史手机布局截图；截图视口与设备模式不同，适合对照结构与信息密度，不作像素差异比较。"}, "interface-desktop": {"before": ["data:image/jpeg;base64,"], "after": ["data:image/jpeg;base64,"], "note": "左侧为本轮首版，右侧为复核通过版；保留实际截图中的状态与素材加载差异。"}, "function-mobile": {"before": ["data:image/jpeg;base64,"], "after": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "note": "修改前为历史手机布局截图；右侧分屏展示当前连接和实体键盘录入布局。视口不同，不作像素差异比较。"}, "function-desktop": {"before": ["data:image/jpeg;base64,"], "after": ["data:image/jpeg;base64,", "data:image/jpeg;base64,"], "note": "左侧为本轮首版，右侧为最终连接区和 Codex 区；上下两图是滚动分屏，之间可能重叠。"}};let moduleName='interface',device='mobile';function render(){const value=sets[moduleName+'-'+device];document.getElementById('note').textContent=value.note;document.getElementById('pair').classList.toggle('mobile',device==='mobile');for(const side of ['before','after']){const target=document.getElementById(side);target.replaceChildren();value[side].forEach((src,i)=>{const img=document.createElement('img');img.src=src;img.alt=(side==='before'?'修改前':'修改后')+'截图 '+(i+1);target.append(img)});target.scrollTop=0}document.querySelectorAll('[data-module]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.module===moduleName));document.querySelectorAll('[data-device]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.device===device))}document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{moduleName=b.dataset.module;render()});document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{device=b.dataset.device;render()});render();